        texto: `
<div style="text-align: justify; line-height: 1.5; " class="">
  La incompetencia por razón de materia, cuantía, grado, turno y territorio, esta última cuando es improrrogable, se declarará de oficio al calificar la demanda o excepcionalmente en cualquier estado y grado del proceso, sin perjuicio de que pueda ser invocada como excepción.</div>
`
