        titulo: "Contienda de competencia",
        texto: `
<div style="text-align: justify; line-height: 1.5; " class="">
  La incompetencia territorial relativa puede ser invocada, excluyentemente, como excepción o como contienda. La contienda de competencia se interpone ante el Juez que el demandado considere competente, dentro de los cinco días de emplazado y ofreciendo los medios probatorios pertinentes.</div><div class="" style="margin-bottom: 15px; text-align: justify; line-height: 1.5;"> El Juez rechazará de plano la contienda propuesta extemporáneamente o cuando es manifiestamente improcedente o temeraria. Cuando la temeridad consista en la creación artificiosa de una competencia territorial, la parte responsable será condenada al pago del monto máximo de la multa prevista por el artículo 46º, y el Juez, de oficio o a pedido de parte, oficiará al Ministerio Público, de ser el caso. </div><div class="" style="margin-bottom: 15px; text-align: justify; line-height: 1.5;">Si el Juez admite la contienda oficiará al Juez de la demanda, pidiéndole que se inhiba de conocerla y solicitando, además, la remisión del expediente. </div><div class="" style="margin-bottom: 15px; text-align: justify; line-height: 1.5;">Con el oficio le anexa copia certificada del escrito de contienda, de sus anexos, de la resolución admisoria y de cualquier otra actuación producida. Adicionalmente al oficio, el Juez de la contienda dará aviso inmediato por fax u otro medio idóneo.</div>
`
