        texto: `
<div style="text-align: justify; line-height: 1.5; " class="">
  Si el Juez de la demanda se considera competente suspenderá el proceso y remitirá todo lo actuado, inclusive el principal, al superior que deba dirimir la competencia, oficiando al Juez de la contienda.</div>
`
