        numero: "61",
        titulo: "Curadoría procesal",
        texto: `
<div style="margin-bottom: 10px; text-align: justify; line-height: 1.5; ">
  El curador procesal es un abogado nombrado por el Juez a pedido de interesado, que interviene en el proceso en los siguientes casos:
</div>
<div data-lne-list="1" data-lne-level="0" data-lne-kind="number" class="" style="display: flex; margin-bottom: 10px; line-height: 1.5; text-align: justify;"><span data-lne-marker="1" style="min-width: 43px; flex: 0 0 43px; font-weight: 400;">1.</span><div>Cuando no sea posible emplazar válidamente al demandado por ser indeterminado, incierto o con domicilio o residencia ignorados, según lo dispuesto por el artículo 435;</div></div><div data-lne-list="1" data-lne-level="0" data-lne-kind="number" class="" style="display: flex; margin-bottom: 10px; line-height: 1.5; text-align: justify;"><span data-lne-marker="1" style="min-width: 43px; flex: 0 0 43px; font-weight: 400;">2.</span><div>Cuando no se pueda establecer o se suspenda la relación procesal por restricción de la capacidad de ejercicio de la parte o de su representante legal;</div></div><div data-lne-list="1" data-lne-level="0" data-lne-kind="number" class="" style="display: flex; margin-bottom: 10px; line-height: 1.5; text-align: justify;"><span data-lne-marker="1" style="min-width: 43px; flex: 0 0 43px; font-weight: 400;">3.</span><div>Cuando exista falta, ausencia o impedimento del representante de la persona con capacidad de ejercicio restringida, según lo dispuesto por el artículo 66; o</div></div>
<div data-lne-list="1" data-lne-level="0" data-lne-kind="number" class="" style="display: flex; margin-bottom: 10px; line-height: 1.5; text-align: justify;"><span data-lne-marker="1" style="min-width: 43px; flex: 0 0 43px; font-weight: 400;">4.</span><div>Cuando no comparece el sucesor procesal, en los casos que así corresponda, según lo dispuesto por el artículo 108.</div></div>
<div style="text-align: justify; line-height: 1.5; " class="">
  Concluye la actuación del curador procesal si la parte o su representante legal comparecen al haber adquirido o recuperado su capacidad procesal.
</div>
`
