        titulo: "Representación procesal del patrimonio autónomo",
        texto: `
<div style="margin-bottom: 15px; text-align: justify; line-height: 1.5; " class="">
  Existe patrimonio autónomo cuando dos o más personas tienen un derecho o interés común respecto de un bien, sin constituir una persona jurídica. </div><div class="" style="margin-bottom: 15px; text-align: justify; line-height: 1.5;">La sociedad conyugal y otros patrimonios autónomos son representados por cualquiera de sus partícipes, si son demandantes. Si son demandados, la representación recae en la totalidad de los que la conforman, siendo de aplicación, en este caso, el artículo 93.
</div>
<div style="text-align: justify; line-height: 1.5; " class="">
  Si se desconociera a uno o más de los integrantes del patrimonio autónomo, se estará a lo dispuesto en el artículo 435. </div><div class="" style="margin-bottom: 15px; text-align: justify; line-height: 1.5;">El que comparece como demandado y oculta que el derecho discutido pertenece a un patrimonio autónomo del que forma parte, se le impondrá una multa no menor de diez ni mayor de cincuenta Unidades de Referencia Procesal, sin perjuicio de lo dispuesto por el artículo 4.</div>
`
