        titulo: "Designación de apoderado judicial",
        texto: `
<div style="text-align: justify; line-height: 1.5; " class="">
  Quien tiene capacidad para comparecer por sí al proceso y disponer de los derechos que en él se discuten, puede nombrar uno o más apoderados. Si son varios, lo serán indistintamente y cada uno de ellos asume la responsabilidad por los actos procesales que realice. </div><div class="" style="margin-bottom: 15px; text-align: justify; line-height: 1.5;">No es válida la designación o actuación de apoderados conjuntos, salvo para los actos de allanamiento, transacción o desistimiento.
</div>
`
