        texto: `
<div style="text-align: justify; line-height: 1.5; " class="">
  El poder para litigar se puede otorgar sólo por escritura pública o por acta ante el Juez del proceso, salvo disposición legal diferente.</div><div class="" style="margin-bottom: 15px; text-align: justify; line-height: 1.5;"> Para su eficacia procesal, el poder no requiere estar inscrito en los Registros Públicos.
</div>
`
