      {
        tipo: "Artículo",
        numero: "75",
        titulo: "Facultades especiales",
        texto: `
<div style="text-align: justify; line-height: 1.5; " class="">
  Se requiere el otorgamiento de facultades especiales para realizar todos los actos de disposición de derechos sustantivos y para demandar, reconvenir, contestar demandas y reconvenciones, desistirse del proceso y de la pretensión, allanarse a la pretensión, conciliar, transigir, someter a arbitraje las pretensiones controvertidas en el proceso, sustituir o delegar la representación procesal y para los demás actos que exprese la ley.</div><div class="" style="margin-bottom: 15px; text-align: justify; line-height: 1.5;"> El otorgamiento de facultades especiales se rige por el principio de literalidad. No se presume la existencia de facultades especiales no conferidas explícitamente.
</div>
`
      },
      {
        tipo: "Artículo",
        numero: "76",
        titulo: "Apoderado común",
        texto: `
<div style="text-align: justify; line-height: 1.5; " class="">
  Cuando diversas personas constituyan una sola parte, actuarán conjuntamente. Si no lo hicieran, el Juez les exigirá la actuación común o el nombramiento de apoderado común en el plazo de diez días, bajo apercibimiento de designarlo por ellos.</div><div class="" style="margin-bottom: 15px; text-align: justify; line-height: 1.5;"> La resolución que contiene el nombramiento es título que acredita la personería del apoderado común, el que necesariamente será uno de los abogados. </div><div class="" style="margin-bottom: 15px; text-align: justify; line-height: 1.5;">La negativa de una persona a la designación de apoderado común o a continuar siendo representada por él, es mérito suficiente para que litigue por separado. </div><div class="" style="margin-bottom: 15px; text-align: justify; line-height: 1.5;">La revocación del poder o renuncia del apoderado común, no surte efecto mientras no se designe uno nuevo y éste se apersone al proceso.
</div>
`
      },
      {
        tipo: "Artículo",
        numero: "77",
        titulo: "Sustitución y delegación del poder",
        texto: `
<div style="text-align: justify; line-height: 1.5; " class="">
  El apoderado puede sustituir sus facultades o delegarlas, siempre que se encuentre expresamente autorizado para ello.</div><div class="" style="margin-bottom: 15px; text-align: justify; line-height: 1.5;"> La sustitución implica el cese de la representación sin posibilidad de reasumirla; la delegación faculta al delegante para revocarla y reasumir la representación. </div><div class="" style="margin-bottom: 15px; text-align: justify; line-height: 1.5;">La actuación del apoderado sustituto o delegado obliga a la parte representada dentro de los límites de las facultades conferidas. </div><div class="" style="margin-bottom: 15px; text-align: justify; line-height: 1.5;">La formalidad para la sustitución o la delegación es la misma que la empleada para el otorgamiento del poder.
</div>
`
      },
      {
        tipo: "Artículo",
        numero: "78",
        titulo: "Cese de la representación judicial",
        texto: `
<div style="text-align: justify; line-height: 1.5; ">
  La representación judicial termina por las mismas razones que causan el cese de la representación o del mandato. Sin embargo, la ejecución de un acto procesal por el representado, no supone la revocación del poder, salvo declaración explícita en tal sentido.
</div>
`
      },
      {
        tipo: "Artículo",
        numero: "79",
        titulo: "Efectos del cese de la representación",
        texto: `
<div style="text-align: justify; line-height: 1.5; " class="">
  En todo caso de finalización de representación que tenga su origen en la decisión del representado capaz de actuar por sí mismo, cualquiera que fuera la causal de cese, éste sólo surtirá efectos desde que la parte comparece al proceso por sí o por medio de nuevo apoderado, con independencia de la fecha o forma en que el cese le haya sido comunicado al anterior. </div><div class="" style="margin-bottom: 15px; text-align: justify; line-height: 1.5;">Cuando el cese de la representación judicial tenga su origen en decisión del apoderado, cualquiera que fuera la razón, surte efecto cinco días después de notificado personalmente el representado u otro cualquiera de sus apoderados, bajo apercibimiento de continuar el proceso en rebeldía. </div><div class="" style="margin-bottom: 15px; text-align: justify; line-height: 1.5;">En caso de muerte o declaración de ausencia, determinación de restricción de la capacidad de ejercicio del representante o del apoderado, remoción o cese de nombramiento del representante legal de una persona con capacidad de ejercicio restringida y circunstancias análogas, se suspenderá el proceso por un plazo máximo de treinta días, mientras se designa representante o curador procesal.</div>
`
      }
