        texto: `
<div style="text-align: justify; line-height: 1.5; " class="">
  Los representantes del Ministerio Público cumplirán los plazos establecidos en la ley, bajo responsabilidad. </div><div class="" style="margin-bottom: 15px; text-align: justify; line-height: 1.5;">Cuando la ley no fije plazo para determinado acto, éste no será mayor que el que corresponde al Juez.
</div>
`
