        tipo: "Artículo",
        numero: "116",
        titulo: "Oportunidad",
        texto: `
<div style="text-align: justify; line-height: 1.5; ">
  El dictamen del Ministerio Público, en los casos en que proceda, será emitido después de actuados los medios probatorios y antes que se expida sentencia.
</div>
`
