        texto: `
<div style="text-align: justify; line-height: 1.5; " class="">
  Los Auxiliares jurisdiccionales son responsables de la formación, conservación y seguridad de los expedientes. Cuidarán, además, de la numeración correlativa y sin interpolación de los folios, que las actas que contienen actuaciones judiciales sean suscritas por el Juez y por los que intervengan en ellas, dando fe de la veracidad de su contenido y las demás responsabilidades que la ley les señala. </div><div class="" style="margin-bottom: 15px; text-align: justify; line-height: 1.5;">La interpolación en la numeración correlativa sólo es procedente por resolución autoritativa del Juez y bajo su responsabilidad.
</div>
`
