        texto: `
<div style="text-align: justify; line-height: 1.5; " class="">
  Los Secretarios de Sala y de Juzgado entregan copias simples de las actas de las actuaciones judiciales concluidas a los intervinientes en ellas que lo soliciten. En cualquier instancia, a pedido de parte y previo pago de la tasa respectiva, el Juez ordenará de plano la expedición de copias certificadas de los folios que se precisen. </div><div class="" style="margin-bottom: 15px; text-align: justify; line-height: 1.5;">La resolución que ordena la expedición de copias certificadas precisará el estado del proceso y formará parte de las copias que se entregan. En la misma resolución el Juez podrá ordenar se expidan copias certificadas de otros folios. </div><div class="" style="margin-bottom: 15px; text-align: justify; line-height: 1.5;">Concluido el proceso, cualquier persona podrá solicitar copias certificadas de folios de un expediente. El Juez puede denegar el pedido en atención a la naturaleza personalísima de la materia controvertida.
</div>
`
