        tipo: "Artículo",
        numero: "155",
        titulo: "Objeto de la notificación",
        texto: `
<div style="text-align: justify; line-height: 1.5; " class="">
  El acto de la notificación tiene por objeto poner en conocimiento de los interesados el contenido de las resoluciones judiciales. El Juez, en decisión motivada, puede ordenar que se notifique a persona ajena al proceso. </div><div class="" style="margin-bottom: 15px; text-align: justify; line-height: 1.5;">Las resoluciones judiciales sólo producen efectos en virtud de notificación hecha con arreglo a lo dispuesto en este Código, salvo los casos expresamente exceptuados.
</div>
`
