        tipo: "Artículo",
        numero: "167",
        titulo: "Notificación por edictos",
        texto: `
<div style="text-align: justify; line-height: 1.5; " class="">
  La publicación de los edictos se hace en el portal web oficial del Poder Judicial. Si ello no fuera posible por las condiciones tecnológicas o lejanía del órgano jurisdiccional, el edicto se publica en el diario de mayor circulación de la circunscripción. A falta de diarios, la publicación se hace en la localidad más próxima que los tuviera, debiéndose además fijar el edicto en la tablilla del Juzgado y en los sitios que aseguren su mayor difusión. </div><div class="" style="margin-bottom: 15px; text-align: justify; line-height: 1.5;">En todos los casos, la publicación debe efectuarse por un período de tres días hábiles acreditándose su realización, agregando al expediente la constancia de su publicación web emitida por el especialista o secretario judicial respectivo y la impresión de la publicación realizada en el portal institucional o, de ser el caso, el primer y el último ejemplar de las publicaciones realizadas en los diarios.</div>
`
