        titulo: "Interrupción del plazo o diferimiento del término para realizar un acto procesal",
        texto: `
<div style="text-align: justify; line-height: 1.5; " class="">
  La declaración de interrupción tiene por efecto cortar el plazo o diferir el término para realizar un acto procesal, produciendo la ineficacia de la fracción del plazo o difiriendo el término transcurrido. </div><div class="" style="margin-bottom: 15px; text-align: justify; line-height: 1.5;">La interrupción será declarada por el Juez en resolución inimpugnable, de oficio o a pedido de parte, sustentándola en la ocurrencia de un hecho imprevisto o que siendo previsible es inevitable. </div><div class="" style="margin-bottom: 15px; text-align: justify; line-height: 1.5;">El plazo para solicitar la declaración de interrupción vence al tercer día de cesado el hecho interruptivo.
</div>
`
