        texto: `
<div style="text-align: justify; line-height: 1.5; " class="">
  Se puede declarar la suspensión del proceso, de oficio o a pedido de parte, en los casos previstos legalmente o cuando a criterio del Juez sea necesario. </div><div class="" style="margin-bottom: 15px; text-align: justify; line-height: 1.5;">El Juez a pedido de parte, suspende la expedición de la sentencia en un proceso siempre que la pretensión planteada en él dependa directamente de lo que debe resolver en otro proceso en el que se haya planteado otra pretensión cuya dilucidación sea esencial y determinante para resolver la pretensión planteada por él. Para ello es necesario que las pretensiones sean conexas, a pesar de lo cual no puedan ser acumuladas, caso contrario, deberá disponerse su acumulación.</div>
`
