        texto: `
<div style="text-align: justify; line-height: 1.5; " class="">
  La conciliación se lleva a cabo ante un centro de conciliación elegido por las partes; no obstante, si ambas lo solicitan, puede el Juez convocarla en cualquier etapa del proceso. El Juez no es recusable por las manifestaciones que pudiera formular en esta audiencia.</div><div class="" style="margin-bottom: 15px; text-align: justify; line-height: 1.5;"> Los Jueces, de oficio o a solicitud de ambas partes, podrán citar a una audiencia de conciliación antes de emitir sentencia, salvo en los casos de violencia familiar. Si la audiencia de conciliación fuera a petición de ambas partes y cualquiera de ellas no concurre a la misma, se le aplica una multa de entre tres y seis unidades de referencia procesal (URP).</div>
`
