        texto: `
<div style="text-align: justify; line-height: 1.5; " class="">
  Cuando proceda la consulta, el expediente es elevado de oficio.</div><div class="" style="margin-bottom: 15px; text-align: justify; line-height: 1.5;"> El Auxiliar jurisdiccional enviará el expediente al superior dentro de cinco días, bajo responsabilidad. </div><div class="" style="margin-bottom: 15px; text-align: justify; line-height: 1.5;">La resolución definitiva se expedirá dentro de los cinco días siguientes a la vista de la causa. No procede el pedido de informe oral. </div><div class="" style="margin-bottom: 15px; text-align: justify; line-height: 1.5;">Durante la tramitación de la consulta, los efectos de la resolución quedan suspendidos.
</div>
`
