        titulo: "Literalidad y destino de la multa",
        texto: `
<div style="text-align: justify; line-height: 1.5; " class="">
  La multa debe ser declarada judicialmente precisándose su monto, el obligado a su pago y la proporción en que la soportan, si fueran más de uno. Cuando no se precise se entiende impuesta en partes iguales.</div><div class="" style="margin-bottom: 15px; text-align: justify; line-height: 1.5;"> La multa es ingreso propio del Poder Judicial. En ningún caso procede su exoneración.
</div>
`
