        texto: `
<div style="text-align: justify; line-height: 1.5; " class="">
  La multa debe pagarse inmediatamente después de impuesta. En caso contrario, devengan intereses legales. </div><div class="" style="margin-bottom: 15px; text-align: justify; line-height: 1.5;">El Juez de la causa requiere al multado del pago. Si luego de diez días de haber sido notificado con la resolución correspondiente no se ha abonado el valor de la misma, se transfiere la resolución de multa para su cobro en la oficina correspondiente, la que dispone de facultades coactivas.</div>
`
