        titulo: "Medios probatorios extemporáneos",
        texto: `
<div style="text-align: justify; line-height: 1.5; " class="">
  Después de interpuesta la demanda, sólo pueden ser ofrecidos los medios probatorios referidos a hechos nuevos y a los mencionados por la otra parte al contestar la demanda o reconvenir. </div><div class="" style="margin-bottom: 15px; text-align: justify; line-height: 1.5;">De presentarse documentos, el Juez concederá traslado a la otra parte para que dentro de cinco días reconozca o niegue la autenticidad de los documentos que se le atribuyen.
</div>
`
