        titulo: "Requisitos y contenido de la contestación a la demanda",
        texto: `
<div style="margin-bottom: 10px; text-align: justify; line-height: 1.5; ">
  Al contestar el demandado debe:
</div>
<div data-lne-list="1" data-lne-level="0" data-lne-kind="number" style="display: flex; margin-bottom: 10px; line-height: 1.5; text-align: justify;">
  <span data-lne-marker="1" style="min-width: 35px; flex: 0 0 35px;">1.</span>
  <div>Observar los requisitos previstos para la demanda, en lo que corresponda;</div>
</div>
<div data-lne-list="1" data-lne-level="0" data-lne-kind="number" style="display: flex; margin-bottom: 10px; line-height: 1.5; text-align: justify;">
  <span data-lne-marker="1" style="min-width: 35px; flex: 0 0 35px;">2.</span>
  <div>Pronunciarse respecto de cada uno de los hechos expuestos en la demanda. El silencio, la respuesta evasiva o la negativa genérica pueden ser apreciados por el Juez como reconocimiento de verdad de los hechos alegados;</div>
</div>
<div data-lne-list="1" data-lne-level="0" data-lne-kind="number" style="display: flex; margin-bottom: 10px; line-height: 1.5; text-align: justify;">
  <span data-lne-marker="1" style="min-width: 35px; flex: 0 0 35px;">3.</span>
  <div>Reconocer o negar categóricamente la autenticidad de los documentos que se le atribuyen, o aceptar o negar, de igual manera, la recepción de documentos que se alega le fueron enviados. El silencio puede ser apreciado por el Juez como reconocimiento o aceptación de recepción de los documentos;</div>
</div>
<div data-lne-list="1" data-lne-level="0" data-lne-kind="number" style="display: flex; margin-bottom: 10px; line-height: 1.5; text-align: justify;">
  <span data-lne-marker="1" style="min-width: 35px; flex: 0 0 35px;">4.</span>
  <div>Exponer los hechos en que funda su defensa en forma precisa, ordenada y clara;</div>
</div>
<div data-lne-list="1" data-lne-level="0" data-lne-kind="number" style="display: flex; margin-bottom: 10px; line-height: 1.5; text-align: justify;">
  <span data-lne-marker="1" style="min-width: 35px; flex: 0 0 35px;">5.</span>
  <div>Ofrecer los medios probatorios; y</div>
</div>
<div data-lne-list="1" data-lne-level="0" data-lne-kind="number" style="display: flex; line-height: 1.5; text-align: justify;">
  <span data-lne-marker="1" style="min-width: 35px; flex: 0 0 35px;">6.</span>
  <div>Incluir su firma o la de su representante o de su apoderado, y la del abogado. El Secretario respectivo certificará la huella digital del demandado analfabeto.</div>
</div>
`
