        tipo: "Artículo",
        numero: "484",
        titulo: "Acumulación sucesiva",
        texto: `
<div style="text-align: justify; line-height: 1.5; " class="">
  Los procesos pendientes de sentencia respecto de las pretensiones accesorias citadas en el artículo 483, se acumulan al proceso principal a pedido de parte. </div><div class="" style="margin-bottom: 15px; text-align: justify; line-height: 1.5;">La acumulación se solicitará acreditando la existencia del expediente, debiendo el Juez ordenar se remita éste dentro de tercer día, bajo responsabilidad. El Juez resolverá su procedencia en decisión inimpugnable.
</div>
`
