        numero: "551",
        titulo: "Inadmisibilidad o improcedencia",
        texto: `
<div style="text-align: justify; line-height: 1.5; " class="">
  El Juez, al calificar la demanda, puede declarar su inadmisibilidad o improcedencia, con arreglo a lo dispuesto por los artículos 426 y 427, respectivamente. </div><div class="" style="margin-bottom: 15px; text-align: justify; line-height: 1.5;">Si declara inadmisible la demanda, concederá al demandante tres días para que subsane la omisión o defecto, bajo apercibimiento de archivar el expediente. Esta resolución es inimpugnable. </div><div class="" style="margin-bottom: 15px; text-align: justify; line-height: 1.5;">Si declara improcedente la demanda, ordenará la devolución de los anexos presentados.
</div>
`
