        tipo: "Artículo",
        numero: "565",
        titulo: "Anexo especial de la contestación",
        texto: `
<div style="text-align: justify; line-height: 1.5; " class="">
  El Juez no admitirá la contestación si el demandado no acompaña la última declaración jurada presentada para la aplicación de su impuesto a la renta o del documento que legalmente la sustituye. De no estar obligado a la declaración citada, acompañará una certificación jurada de sus ingresos, con firma legalizada. </div><div class="" style="margin-bottom: 15px; text-align: justify; line-height: 1.5;">En este caso es de aplicación el segundo párrafo del artículo 564.
</div>
`
