        titulo: "Tercero con título o sin él",
        texto: `
<div style="text-align: justify; line-height: 1.5; " class="">
  Si el predio es ocupado por un tercero ajeno a la relación establecida entre el demandante y la persona a quien éste le cedió la posesión, el demandante debe denunciarlo en su demanda. El denunciado será notificado con la demanda y podrá participar en el proceso. </div><div class="" style="margin-bottom: 15px; text-align: justify; line-height: 1.5;">Si al momento de la notificación del admisorio se advierte la presencia de tercero, quien lo notifique lo instruirá del proceso iniciado, su derecho a participar en él y el efecto que va a producirle la sentencia. </div><div class="" style="margin-bottom: 15px; text-align: justify; line-height: 1.5;">El tercero puede actuar como litisconsorte voluntario del demandado desde la audiencia única. </div><div class="" style="margin-bottom: 15px; text-align: justify; line-height: 1.5;">Si durante la audiencia se advierte que el tercero carece de título posesorio, el Juez aplicará lo dispuesto por el artículo 107.
</div>
`
