        texto: `
<div style="text-align: justify; line-height: 1.5; " class="">
  Además de la dirección domiciliaria indicada en la demanda, ésta debe ser notificada en el predio materia de la pretensión, si fuera distinta. </div><div class="" style="margin-bottom: 15px; text-align: justify; line-height: 1.5;">Si el predio no tiene a la vista numeración que lo identifique, el notificador cumplirá su cometido inquiriendo a los vecinos y redactando un acta sobre lo ocurrido.
</div>
`
