        tipo: "Artículo",
        numero: "603",
        titulo: "Interdicto de recobrar",
        texto: `
<div style="text-align: justify; line-height: 1.5; " class="">
  Procede cuando el poseedor es despojado de su posesión, siempre que no haya mediado proceso previo. </div><div class="" style="margin-bottom: 15px; text-align: justify; line-height: 1.5;">Sin embargo, si se prueba que el despojo ocurrió en ejercicio del derecho contenido en el artículo 920 del Código Civil, la demanda será declarada improcedente. </div><div class="" style="margin-bottom: 15px; text-align: justify; line-height: 1.5;">Procede a pedido de parte la solicitud de posesión provisoria del bien una vez que haya sido admitida la demanda, la que se sujeta a los requisitos y trámites de la medida cautelar.</div>
`
