        tipo: "Artículo",
        numero: "630",
        titulo: "Cancelación de la medida",
        texto: `
<div style="text-align: justify; line-height: 1.5; " class="">
  Si la sentencia en primera instancia declara infundada la demanda, la medida cautelar queda cancelada, aunque aquella hubiere sido impugnada. Sin embargo, a pedido del solicitante el Juez podrá mantener la vigencia de la medida hasta su revisión por la instancia superior, siempre que se ofrezca contracautela de naturaleza real o fianza solidaria.</div>
`
