        texto: `
<div style="text-align: justify; line-height: 1.5; " class="">
  En un proceso en trámite, el cuaderno cautelar se forma con copia simple de la demanda, sus anexos y la resolución admisoria. Estas se agregan a la solicitud cautelar y a sus documentos sustentatorios. Para la tramitación de este recurso está prohibido el pedido del expediente principal.</div>
`
