        texto: `
<div style="text-align: justify; line-height: 1.5; " class="">
  Cuando la medida recae sobre derechos de crédito u otros bienes en posesión de terceros, cuyo titular es el afectado con ella, puede ordenarse al poseedor retener el pago a la orden del Juzgado, depositando el dinero en el Banco de la Nación. Tratándose de otros bienes, el retenedor asume las obligaciones y responsabilidades del depositario, salvo que los ponga a disposición del Juez. </div><div class="" style="margin-bottom: 15px; text-align: justify; line-height: 1.5;">Si el poseedor de los derechos de crédito es una entidad financiera, el Juez ordenará la retención mediante envío del mandato vía correo electrónico, trabándose la medida inmediatamente o excepcionalmente por cualquier otro medio fehaciente que deje constancia de su decisión.</div><div class="" style="margin-bottom: 15px; text-align: justify; line-height: 1.5;"> Para tal efecto, todas las Entidades Financieras deberán comunicar a la Superintendencia de Banca y Seguros la dirección electrónica a donde se remitirá la orden judicial de retención.</div>
`
