        texto: `
<div style="text-align: justify; line-height: 1.5; " class="">
  Registros Públicos Cuando la pretensión discutida en el proceso principal está referida a derechos inscritos, la medida cautelar puede consistir en la anotación de la demanda en el registro respectivo. Para su ejecución, el Juez remitirá partes al registrador, los que incluirán copia íntegra de la demanda, de la resolución que la admite y de la cautelar. </div><div class="" style="margin-bottom: 15px; text-align: justify; line-height: 1.5;">El registrador cumplirá la orden por su propio texto, siempre que la medida resulte compatible con el derecho ya inscrito. La certificación registral de la inscripción se agrega al expediente. </div><div class="" style="margin-bottom: 15px; text-align: justify; line-height: 1.5;">La anotación de la demanda no impide la transferencia del bien ni las afectaciones posteriores, pero otorga prevalencia a quien ha obtenido esta medida.
</div>
`
