        titulo: "Trámite",
        texto: `
<div style="text-align: justify; line-height: 1.5; " class="">
  Si hay contradicción y/o excepciones procesales o defensas previas, se concede traslado al ejecutante, quien deberá absolverla dentro de tres días proponiendo los medios probatorios pertinentes. Con la absolución o sin ella, el Juez resolverá mediante un auto, observando las reglas para el saneamiento procesal, y pronunciándose sobre la contradicción propuesta. </div><div class="" style="margin-bottom: 15px; text-align: justify; line-height: 1.5;">Cuando la actuación de los medios probatorios lo requiera o el Juez lo estime necesario, señalará día y hora para la realización de una audiencia, la que se realizará con las reglas establecidas para la audiencia única. </div><div class="" style="margin-bottom: 15px; text-align: justify; line-height: 1.5;">Si no se formula contradicción, el Juez expedirá un auto sin más trámite, ordenando llevar adelante la ejecución.</div>
`
