        texto: `
<div style="text-align: justify; line-height: 1.5; " class="">
  El plazo para interponer apelación contra el auto, que resuelve la contradicción es de tres días contados, desde el día siguiente a su notificación. El auto que resuelve la contradicción, poniendo fin al proceso único de ejecución es apelable con efecto suspensivo. </div><div class="" style="margin-bottom: 15px; text-align: justify; line-height: 1.5;">En todos los casos que en este Título se conceda apelación con efecto suspensivo, es de aplicación el trámite previsto en el artículo 376. Si la apelación es concedida sin efecto suspensivo, tendrá la calidad de diferida, siendo de aplicación el artículo 369 en lo referente a su trámite.</div>
`
