  <div>La intimación al ejecutado para que entregue el bien dentro del plazo fijado por el Juez atendiendo a la naturaleza de la obligación, bajo apercibimiento de procederse a su entrega forzada; y en caso de no realizarse la entrega por destrucción, deterioro, sustracción u ocultamiento atribuible al obligado, se le requerirá para el pago de su valor, si así fue demandado.</div>
