        tipo: "Artículo",
        numero: "722",
        titulo: "Contradicción",
        texto: `
<div style="text-align: justify; line-height: 1.5; " class="">
  El ejecutado, en el mismo plazo que tiene para pagar, puede contradecir con arreglo a las disposiciones generales.</div>
`
