        tipo: "Artículo",
        numero: "759",
        titulo: "Intervención del Ministerio",
        texto: `
<div style="text-align: justify; line-height: 1.5; " class="">
  Público Cuando se haga referencia al Ministerio Público en los procesos regulados en el siguiente título, éste será notificado con las resoluciones que se expidan en cada proceso, para los efectos del artículo 159, numeral 2, de la Constitución Política del Perú. No emite dictamen. </div><div class="" style="margin-bottom: 15px; text-align: justify; line-height: 1.5;">En los procesos de sucesión intestada no es necesaria la notificación al Ministerio Público; salvo que entre los herederos existan menores de edad o Consejo de Familia constituido con anterioridad.</div>
`
