        texto: `
<div style="text-align: justify; line-height: 1.5; " class="">
  Terminado el inventario y la valorización, en su caso, se pondrá de manifiesto lo actuado por diez días en el local del Juzgado. Si no se pide exclusión o resuelta ésta, el Juez aprobará el inventario y mandará que se protocolice notarialmente. </div><div class="" style="margin-bottom: 15px; text-align: justify; line-height: 1.5;">El inventario no es título para solicitar la posesión de los bienes.
</div>
`
