        tipo: "Artículo",
        numero: "805",
        titulo: "Falta de contradicción y audiencia",
        texto: `
<div style="text-align: justify; line-height: 1.5; " class="">
  Si el acreedor no contradice el ofrecimiento dentro de los cinco días del emplazamiento, en la audiencia el Juez declara la validez del ofrecimiento y recibirá el pago, teniendo presente lo dispuesto en el artículo 807. </div><div class="" style="margin-bottom: 15px; text-align: justify; line-height: 1.5;">En caso de inconcurrencia del emplazado, se procederá en la forma establecida en el párrafo anterior. </div><div class="" style="margin-bottom: 15px; text-align: justify; line-height: 1.5;">Si el solicitante no concurre a la audiencia, o si concurriendo no realiza el pago en la forma ofrecida, el Juez declarará inválido el ofrecimiento y le impondrá una multa no menor de una ni mayor de tres Unidades de Referencia Procesal. Esta decisión es inimpugnable. </div><div class="" style="margin-bottom: 15px; text-align: justify; line-height: 1.5;">Si el emplazado acepta el ofrecimiento, el Juez ordenará que la prestación le sea entregada de manera directa e inmediata.
</div>
`
