        texto: `
<div style="margin-bottom: 15px; text-align: justify; line-height: 1.5;" class="">Cada dos años los Colegios de Abogados, de Ingenieros, de Contadores, de Médicos y los demás cuyos profesionales puedan realizar pericias, aprueban y publican en el diario “El Peruano”, “Normas Orientadoras de Honorarios Profesionales”, que serán de obligatoria observancia por los Jueces para la determinación de los honorarios profesionales. </div><div class="" style="margin-bottom: 15px; text-align: justify; line-height: 1.5;">En defecto de actualización, los Jueces aplican los índices de precios al consumidor.</div>
`
